# Rebuilds definition/model/eclipselink-orm.xml from the database: init over selection.yaml,
# then the validated edits below. Run from the repository root, with the database running:
#
#   samples/adventureworks/shape.sh <drivers-dir>
#
# The edits only rename, remove, lock and describe; every one is checked against the database as it is
# made.
set -euo pipefail

DRIVERS=${1:?usage: shape.sh <dir with the PostgreSQL JDBC driver>}
HERE=samples/adventureworks
JAR=$(ls target/eclipselink-mcp-server-*.jar | grep -v original | head -1)
export AW_DB_URL=${AW_DB_URL:-jdbc:postgresql://localhost:5432/adventureworks}
export AW_READER_PASSWORD=${AW_READER_PASSWORD:-reader}
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT
OUT=$WORK/adventureworks

java -jar "$JAR" init --url "$AW_DB_URL" --user mcp_reader --password-env AW_READER_PASSWORD \
    --drivers "$DRIVERS" --selection "$HERE/selection.yaml" --name adventureworks --out "$OUT"
# init names the URL variable after the server; the edits below validate through AW_DB_URL.
sed -i.bak 's/ADVENTUREWORKS_DB_URL/AW_DB_URL/; s/ADVENTUREWORKS_DB_USER/AW_DB_USER/' "$OUT/eclipselink-mcp.yaml"

edit() { java -jar "$JAR" edit --definition "$OUT" --drivers "$DRIVERS" "$@"; }

# ---- 1. Remove what agents do not need ------------------------------------------------------------------
# Row timestamps, except on the three tables the write operations change (they set them).
for e in Customer Store Salesperson Salespersonquotahistory Salesterritory Specialoffer Product \
         Productsubcategory Productcategory Productlistpricehistory Shipmethod Person Businessentity \
         Businessentityaddress Address Addresstype Stateprovince; do
    edit remove-attribute "$e" modifieddate
done
# Card details and keys of tables outside the model; a geography value as raw bytes.
edit remove-attribute Salesorderheader creditcardid creditcardapprovalcode currencyrateid
edit remove-attribute Address spatiallocation
# Reverse lists that are large or that nobody navigates (an address's orders, a product's every sale).
edit remove-attribute Address salesorderheadersByBilltoaddress salesorderheadersByShiptoaddress businessentityaddress
edit remove-attribute Shipmethod salesorderheaders
edit remove-attribute Specialoffer salesorderdetails
edit remove-attribute Product salesorderdetails
edit remove-attribute Salesterritory salesorderheaders customers stateprovinces
edit remove-attribute Salesperson salesorderheaders
edit remove-attribute Person customers
edit remove-attribute Stateprovince address
edit remove-attribute Addresstype businessentityaddress

# ---- 2. AdventureWorks' own names (PostgreSQL folds unquoted names to lower case) ---------------------------
while read -r from to; do
    edit rename-entity "$from" "$to"
done <<'NAMES'
Salesorderheader SalesOrderHeader
Salesorderdetail SalesOrderDetail
Salesperson SalesPerson
Salespersonquotahistory SalesPersonQuotaHistory
Salesterritory SalesTerritory
Specialoffer SpecialOffer
Productsubcategory ProductSubcategory
Productcategory ProductCategory
Productlistpricehistory ProductListPriceHistory
Shipmethod ShipMethod
Businessentity BusinessEntity
Businessentityaddress BusinessEntityAddress
Addresstype AddressType
Stateprovince StateProvince
Emailaddress EmailAddress
NAMES

while read -r entity from to; do
    edit rename-attribute "$entity" "$from" "$to"
done <<'NAMES'
SalesOrderHeader salesorderid salesOrderId
SalesOrderHeader revisionnumber revisionNumber
SalesOrderHeader orderdate orderDate
SalesOrderHeader duedate dueDate
SalesOrderHeader shipdate shipDate
SalesOrderHeader onlineorderflag onlineOrderFlag
SalesOrderHeader purchaseordernumber purchaseOrderNumber
SalesOrderHeader accountnumber accountNumber
SalesOrderHeader subtotal subTotal
SalesOrderHeader taxamt taxAmt
SalesOrderHeader totaldue totalDue
SalesOrderHeader modifieddate modifiedDate
SalesOrderHeader billtoaddress billToAddress
SalesOrderHeader shiptoaddress shipToAddress
SalesOrderHeader shipmethod shipMethod
SalesOrderHeader salesperson salesPerson
SalesOrderHeader salesorderdetails lines
SalesOrderDetail salesorderdetailid salesOrderDetailId
SalesOrderDetail carriertrackingnumber carrierTrackingNumber
SalesOrderDetail orderqty orderQty
SalesOrderDetail unitprice unitPrice
SalesOrderDetail unitpricediscount unitPriceDiscount
SalesOrderDetail modifieddate modifiedDate
SalesOrderDetail salesorder salesOrder
SalesOrderDetail specialoffer specialOffer
Customer customerid customerId
Customer salesorderheaders salesOrders
Store businessentityid businessEntityId
Store businessentity businessEntity
Store salesperson salesPerson
SalesPerson businessentityid businessEntityId
SalesPerson salesquota salesQuota
SalesPerson commissionpct commissionPct
SalesPerson salesytd salesYtd
SalesPerson saleslastyear salesLastYear
SalesPerson salespersonquotahistories quotaHistory
SalesPersonQuotaHistory businessentityid businessEntityId
SalesPersonQuotaHistory quotadate quotaDate
SalesPersonQuotaHistory salesquota salesQuota
SalesPersonQuotaHistory businessentity salesPerson
SalesTerritory territoryid territoryId
SalesTerritory countryregioncode countryRegionCode
SalesTerritory salesytd salesYtd
SalesTerritory saleslastyear salesLastYear
SalesTerritory costytd costYtd
SalesTerritory costlastyear costLastYear
SalesTerritory salespersons salesPeople
SpecialOffer specialofferid specialOfferId
SpecialOffer discountpct discountPct
SpecialOffer startdate startDate
SpecialOffer enddate endDate
SpecialOffer minqty minQty
SpecialOffer maxqty maxQty
Product productid productId
Product productnumber productNumber
Product makeflag makeFlag
Product finishedgoodsflag finishedGoodsFlag
Product safetystocklevel safetyStockLevel
Product reorderpoint reorderPoint
Product standardcost standardCost
Product listprice listPrice
Product sizeunitmeasurecode sizeUnitMeasureCode
Product weightunitmeasurecode weightUnitMeasureCode
Product daystomanufacture daysToManufacture
Product productline productLine
Product productmodelid productModelId
Product sellstartdate sellStartDate
Product sellenddate sellEndDate
Product discontinueddate discontinuedDate
Product productsubcategory productSubcategory
Product productlistpricehistories listPriceHistory
ProductSubcategory productsubcategoryid productSubcategoryId
ProductSubcategory productcategory productCategory
ProductCategory productcategoryid productCategoryId
ProductCategory productsubcategories productSubcategories
ProductListPriceHistory productid productId
ProductListPriceHistory startdate startDate
ProductListPriceHistory enddate endDate
ProductListPriceHistory listprice listPrice
ShipMethod shipmethodid shipMethodId
ShipMethod shipbase shipBase
ShipMethod shiprate shipRate
Person businessentityid businessEntityId
Person persontype personType
Person namestyle nameStyle
Person firstname firstName
Person middlename middleName
Person lastname lastName
Person emailpromotion emailPromotion
Person businessentity businessEntity
Person emailaddress emailAddresses
BusinessEntity businessentityid businessEntityId
BusinessEntity businessentityaddress addresses
BusinessEntityAddress businessentityid businessEntityId
BusinessEntityAddress addressid addressId
BusinessEntityAddress addresstypeid addressTypeId
BusinessEntityAddress addresstype addressType
BusinessEntityAddress businessentity businessEntity
Address addressid addressId
Address addressline1 addressLine1
Address addressline2 addressLine2
Address postalcode postalCode
Address stateprovince stateProvince
StateProvince stateprovinceid stateProvinceId
StateProvince stateprovincecode stateProvinceCode
StateProvince countryregioncode countryRegionCode
StateProvince isonlystateprovinceflag isOnlyStateProvinceFlag
AddressType addresstypeid addressTypeId
EmailAddress businessentityid businessEntityId
EmailAddress emailaddressid emailAddressId
EmailAddress emailaddress emailAddress
EmailAddress modifieddate modifiedDate
EmailAddress businessentity person
NAMES

# ---- 3. Locking and descriptions ----------------------------------------------------------------------------
# A line has no version of its own: it is locked through its order's revision number.
edit lock-through SalesOrderDetail salesOrder
edit describe SalesOrderHeader.status "1 in process, 2 approved, 3 backordered, 4 rejected, 5 shipped, 6 cancelled"
edit describe SalesOrderHeader.revisionNumber "Optimistic lock version: send it back unchanged with a change to the order or its lines"
edit describe SalesOrderHeader.lines "The order's lines"
edit describe SalesOrderDetail.salesOrder "The order this line belongs to"
edit describe SalesOrderDetail.product "The product sold"
edit describe SalesOrderDetail.specialOffer "The discount applied; 1 is No Discount"
edit describe Customer.salesOrders "The customer's orders"
edit describe BusinessEntity "A person, store or vendor; its addresses are shared by all three"
edit describe BusinessEntity.addresses "Addresses of this person or store, with their type (billing, shipping, ...)"
edit describe EmailAddress.version "Optimistic lock version"

# The committed model carries the repository's license header after the XML declaration.
HEADER='<!--
  Copyright (c) 2026 Doug Clarke.

  This program and the accompanying materials are made available under the
  terms of the Eclipse Public License v. 2.0 which is available at
  http://www.eclipse.org/legal/epl-2.0,
  or the Eclipse Distribution License v. 1.0 which is available at
  http://www.eclipse.org/org/documents/edl-v10.php.

  SPDX-License-Identifier: EPL-2.0 OR BSD-3-Clause

  Some portions generated by Claude.
-->
<!-- Generated by samples/adventureworks/shape.sh (init over selection.yaml, then validated edits).
     To change it, change shape.sh and run it again. -->'
mkdir -p "$HERE/definition/model"
{ head -1 "$OUT/model/eclipselink-orm.xml"; printf '%s\n' "$HEADER"; tail -n +4 "$OUT/model/eclipselink-orm.xml"; } \
    > "$HERE/definition/model/eclipselink-orm.xml"
echo "Shaped model written to $HERE/definition/model"
